import java.util.*;import java.math.BigInteger;
public class DiffieHellmanKeyExchange {public static void main(String[]z){Scanner sc=new Scanner(System.in);System.out.print("Enter prime number: ");BigInteger p=sc.nextBigInteger();System.out.print("Enter generator: ");BigInteger g=sc.nextBigInteger();System.out.print("Enter Alice's private key: ");BigInteger a=sc.nextBigInteger();System.out.print("Enter Bob's private key: ");BigInteger b=sc.nextBigInteger();if(!p.isProbablePrime(50)||g.compareTo(BigInteger.ONE)<=0||g.compareTo(p)>=0||a.signum()<0||b.signum()<0){System.out.println("Use a prime p, 1 < g < p, and nonnegative private keys.");return;}BigInteger A=g.modPow(a,p),B=g.modPow(b,p),key1=B.modPow(a,p),key2=A.modPow(b,p);System.out.println("Alice's public key: "+A);System.out.println("Bob's public key: "+B);System.out.println("Alice's shared key: "+key1);System.out.println("Bob's shared key: "+key2);System.out.println("Keys match: "+key1.equals(key2));}}
